  const [search,setSearch]=useState(""),[workSales,setWorkSales]=useState(sales),[startDate,setStartDate]=useState(localDateValue),[endDate,setEndDate]=useState(localDateValue),[filterError,setFilterError]=useState(""),[loadError,setLoadError]=useState(""),[invoiceSale,setInvoiceSale]=useState(null),[saleLoading,setSaleLoading]=useState(false);
