  const openIssue=async sale=>{setSaleLoading(true);setLoadError("");setInvoiceSale({databaseId:sale.databaseId,id:sale.id,items:[]});try{setInvoiceSale(await onLoadSale(sale.databaseId))}catch(loadFailure){setLoadError(loadFailure.message)}finally{setSaleLoading(false)}};
  return <Page><div className="sales-list-page invoice-issue-page"><Toolbar search={search} setSearch={setSearch} onSearch={()=>{}} onRefresh={()=>loadRows()} busy={loading} placeholder={t("searchSalesForInvoice")}/><div className="date-filter"><label>{t("startDate")}<input type="date" value={startDate} max={endDate||undefined} onChange={event=>setStartDate(event.target.value)}/></label><span>—</span><label>{t("endDate")}<input type="date" value={endDate} min={startDate||undefined} onChange={event=>setEndDate(event.target.value)}/></label><button className="primary" onClick={()=>loadRows()} disabled={loading}><Search size={16}/>{t("queryDateRange")}</button><button className="outline" onClick={()=>{const today=localDateValue();setStartDate(today);setEndDate(today);loadRows({startDate:today,endDate:today})}} disabled={loading}>{t("today")}</button></div>{(filterError||loadError||error)&&<div className="form-error page-error">{filterError||loadError||error}</div>}<div className="table-wrap invoice-issue-table"><table><thead><tr><th>{t("salesOrderNo")}</th><th>ID</th><th>{t("orderDate")}</th><th>{t("salesperson")}</th><th>{t("customer")}</th><th>{t("itemDetails")}</th><th>{t("quantity")}</th><th>{t("currencyChoice")}</th><th>{t("total")}</th><th>{t("invoiceStatus")}</th><th>{t("actions")}</th></tr></thead><tbody>{rows.map(sale=>{const state=invoiceState(sale);return <tr key={sale.databaseId}><td><b>{sale.id}</b></td><td>{sale.databaseId}</td><td>{sale.date}</td><td>{sale.salesperson}</td><td>{sale.customer||t("walkInCustomer")}</td><td>{sale.itemCount}</td><td>{sale.qty}</td><td>{sale.currency}</td><td><b>{money(sale.total,sale.currency)}</b></td><td><span className={`invoice-status ${state.status}`}>{t(state.status==="none"?"notInvoiced":`invoiceLifecycle_${state.status}`)}</span></td><td><button className="primary compact-action" disabled={state.disabled} onClick={()=>openIssue(sale)}><FileText size={15}/>{t("issueInvoice")}</button></td></tr>})}</tbody></table>{!rows.length&&<div className="empty">{t("noSalesInDateRange")}</div>}</div>{invoiceSale&&<InvoiceModal sale={invoiceSale} loading={saleLoading} loadError={loadError} settings={settings} onClose={()=>setInvoiceSale(null)} onCreate={onCreate} onOpenPdf={onOpenPdf}/>}</div></Page>;
