function UserModal({onClose,onSave}) {
  const {t}=useI18n();
  const [form,setForm]=useState({username:"",displayName:"",password:"",role:"sales"}),[saving,setSaving]=useState(false),[error,setError]=useState("");
  const save=async()=>{if(!form.username||form.password.length<8)return setError(t("userRequirements"));setSaving(true);setError("");try{await onSave(form)}catch(e){setError(`${t("userCreateFailed")}：${e.message}`)}finally{setSaving(false)}};
  return <Modal title={t("addUser")} onClose={onClose}><div className="form-grid"><label>{t("username")}<input value={form.username} onChange={e=>setForm({...form,username:e.target.value})}/></label><label>{t("displayName")}<input value={form.displayName} onChange={e=>setForm({...form,displayName:e.target.value})}/></label><label>{t("password")}<input type="password" value={form.password} onChange={e=>setForm({...form,password:e.target.value})}/></label><label>{t("role")}<select value={form.role} onChange={e=>setForm({...form,role:e.target.value})}>{roleOptions.map(role=><option key={role} value={role}>{t(`role_${role}`)}</option>)}</select></label></div>{error&&<div className="form-error">{error}</div>}<div className="modal-actions"><button className="outline" onClick={onClose} disabled={saving}>{t("cancel")}</button><button className="primary" onClick={save} disabled={saving}>{saving?t("saving"):t("save")}</button></div></Modal>
}

function Page({children}) {return <div className="page-content">{children}</div>}
function Modal({title,onClose,children,wide=false}) {return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><div className={`modal${wide?" modal-wide":""}`}><div className="modal-head"><b>{title}</b><button className="icon-btn" onClick={onClose}><X size={19}/></button></div>{children}</div></div>}

export function App() {
  const [session,setSession]=useState(getStoredSession);
  const [page,setPage]=useState("dashboard"),[openTabs,setOpenTabs]=useState(["dashboard"]),[menuOpen,setMenuOpen]=useState(false);
  const [products,setProducts]=useState([]),[categoryRecords,setCategoryRecords]=useState([]),[customers,setCustomers]=useState([]),[purchases,setPurchases]=useState([]),[sales,setSales]=useState([]),[pickingSales,setPickingSales]=useState([]),[invoices,setInvoices]=useState([]),[users,setUsers]=useState([]);
  const [systemSettings,setSystemSettings]=useState(defaultSystemSettings);
  const [editingSale,setEditingSale]=useState(null),[settlementSale,setSettlementSale]=useState(null),[settlementLoading,setSettlementLoading]=useState(false),[settlementError,setSettlementError]=useState(""),[deliverySale,setDeliverySale]=useState(null),[deliveryLoading,setDeliveryLoading]=useState(false),[deliveryError,setDeliveryError]=useState("");
  const [salesFilters,setSalesFilters]=useState(defaultSalesFilters),[pickingFilters,setPickingFilters]=useState(defaultSalesFilters);
  const [dashboardSummary,setDashboardSummary]=useState(null),[reportSummary,setReportSummary]=useState(null);
  const [dataLoading,setDataLoading]=useState(false),[dataError,setDataError]=useState("");
  useEffect(()=>{const close=()=>setMenuOpen(false);window.addEventListener("resize",close);return()=>window.removeEventListener("resize",close)},[]);
  const openPage=nextPage=>{setOpenTabs(current=>current.includes(nextPage)?current:[...current,nextPage]);setPage(nextPage)};
  const closePage=(tab,event)=>{event?.stopPropagation();if(tab==="dashboard")return;setOpenTabs(current=>{const index=current.indexOf(tab),next=current.filter(item=>item!==tab);if(page===tab)setPage(next[Math.max(0,index-1)]||"dashboard");return next});if(tab==="scanSales")setEditingSale(null);if(tab==="saleSettlement"){setSettlementSale(null);setSettlementError("")}if(tab==="deliveryNote"||tab==="pickingNote"){setDeliverySale(null);setDeliveryError("")}};
  const logout=()=>{clearStoredSession();setSession(null);setPage("dashboard");setOpenTabs(["dashboard"]);setProducts([]);setCategoryRecords([]);setCustomers([]);setPurchases([]);setSales([]);setPickingSales([]);setInvoices([]);setUsers([]);setSystemSettings(defaultSystemSettings);setEditingSale(null);setSettlementSale(null);setDeliverySale(null);setSalesFilters(defaultSalesFilters());setPickingFilters(defaultSalesFilters())};
  const handleError=(error)=>{if(error instanceof ApiError&&error.status===401){logout();return}setDataError(error.message)};
  const loadAll=async(token=session?.token)=>{if(!token)return;setDataLoading(true);setDataError("");try{const nextIdentity=await fetchCurrentUser(token),role=nextIdentity.role;const [nextProducts,nextCategoryRecords,nextCustomers,nextPurchases,nextSales,nextPickingSales,nextInvoices,nextDashboard,nextReport,nextUsers,nextSettings]=await Promise.all([fetchProducts(token),fetchCategories(token),["admin","sales","finance"].includes(role)?fetchCustomers(token):Promise.resolve([]),["admin","purchasing","warehouse","finance"].includes(role)?fetchPurchases(token):Promise.resolve([]),["admin","sales","finance"].includes(role)?fetchSales(token,salesFilters):Promise.resolve([]),["admin","warehouse"].includes(role)?fetchPickingSales(token,pickingFilters):Promise.resolve([]),["admin","sales","finance"].includes(role)?fetchInvoices(token):Promise.resolve([]),fetchDashboard(token),["admin","finance"].includes(role)?fetchReportSummary(token):Promise.resolve(null),role==="admin"?fetchUsers(token):Promise.resolve([]),fetchSettings(token)]);setProducts(nextProducts);setCategoryRecords(nextCategoryRecords);setCustomers(nextCustomers);setPurchases(nextPurchases);setSales(nextSales);setPickingSales(nextPickingSales);setInvoices(nextInvoices);setDashboardSummary(nextDashboard);setReportSummary(nextReport);setUsers(nextUsers);setSystemSettings(nextSettings);const refreshedSession={...session,user:nextIdentity};storeSession(refreshedSession);setSession(refreshedSession)}catch(error){handleError(error)}finally{setDataLoading(false)}};
  const loadProducts=async(search="",categoryId="")=>{if(!session?.token)return;setDataLoading(true);setDataError("");try{setProducts(await fetchProducts(session.token,search,categoryId))}catch(error){handleError(error)}finally{setDataLoading(false)}};
  const loadCustomers=async(search="")=>{if(!session?.token)return;setDataLoading(true);setDataError("");try{setCustomers(await fetchCustomers(session.token,search))}catch(error){handleError(error)}finally{setDataLoading(false)}};
  const refreshInvoices=async()=>{if(!session?.token)return;setDataLoading(true);setDataError("");try{setInvoices(await fetchInvoices(session.token))}catch(error){handleError(error)}finally{setDataLoading(false)}};
  const refreshPurchases=async()=>{if(!session?.token)return;setDataLoading(true);setDataError("");try{setPurchases(await fetchPurchases(session.token))}catch(error){handleError(error)}finally{setDataLoading(false)}};
  const refreshSales=async(filters=salesFilters)=>{if(!session?.token)return;setSalesFilters(filters);setDataLoading(true);setDataError("");try{setSales(await fetchSales(session.token,filters))}catch(error){handleError(error)}finally{setDataLoading(false)}};
  const refreshPickingSales=async(filters=pickingFilters)=>{if(!session?.token)return;setPickingFilters(filters);setDataLoading(true);setDataError("");try{setPickingSales(await fetchPickingSales(session.token,filters))}catch(error){handleError(error)}finally{setDataLoading(false)}};
  const refreshReport=()=>["admin","finance"].includes(session?.user?.role)?fetchReportSummary(session.token):Promise.resolve(reportSummary);
  useEffect(()=>{if(session?.token)loadAll(session.token)},[session?.token]);
  const login=async(username,password)=>{const next=await loginRequest(username,password);storeSession(next);setSession(next)};
  const syncCategories=async()=>{const next=await fetchCategories(session.token);setCategoryRecords(next);return next};
  const addProduct=async(product)=>{const created=await createProductRequest(session.token,product);setProducts(current=>[created,...current]);const [,nextDashboard,nextReport]=await Promise.all([syncCategories(),fetchDashboard(session.token),refreshReport()]);setDashboardSummary(nextDashboard);setReportSummary(nextReport)};
  const changeProduct=async(id,product)=>{const updated=await updateProductRequest(session.token,id,product);setProducts(current=>current.map(item=>item.id===updated.id?updated:item));await syncCategories();return updated};
  const addCategory=async category=>{await createCategoryRequest(session.token,category);await syncCategories()};
  const changeCategory=async(id,category)=>{await updateCategoryRequest(session.token,id,category);const next=await syncCategories();setProducts(await fetchProducts(session.token));return next.find(item=>Number(item.id)===Number(id))};
  const uploadCategoryImage=async(id,file)=>{const updated=await uploadCategoryImageRequest(session.token,id,file);setCategoryRecords(current=>current.map(category=>Number(category.id)===Number(id)?updated:category));return updated};
  const removeCategoryImage=async id=>{const updated=await deleteCategoryImageRequest(session.token,id);setCategoryRecords(current=>current.map(category=>Number(category.id)===Number(id)?updated:category));return updated};
  const uploadProductImage=async(id,file)=>{const updated=await uploadProductImageRequest(session.token,id,file);setProducts(current=>current.map(item=>item.id===updated.id?updated:item));return updated};
  const removeProductImage=async id=>{const updated=await deleteProductImageRequest(session.token,id);setProducts(current=>current.map(item=>item.id===updated.id?updated:item));return updated};
  const loadProductDetail=async id=>fetchProduct(session.token,id);
  const addCustomer=async(customer)=>{const created=await createCustomerRequest(session.token,customer);setCustomers(current=>[created,...current]);setDashboardSummary(await fetchDashboard(session.token))};
  const changeCustomer=async(id,customer)=>{const updated=await updateCustomerRequest(session.token,id,customer);setCustomers(current=>current.map(item=>Number(item.id)===Number(id)?updated:item));return updated};
  const addPurchase=async(purchase)=>{await createPurchaseRequest(session.token,purchase);const [nextProducts,nextPurchases,nextDashboard,nextReport]=await Promise.all([fetchProducts(session.token),fetchPurchases(session.token),fetchDashboard(session.token),refreshReport()]);setProducts(nextProducts);setPurchases(nextPurchases);setDashboardSummary(nextDashboard);setReportSummary(nextReport)};
  const addSale=async(sale)=>{const created=await createSaleRequest(session.token,sale);const [nextProducts,nextSales,nextDashboard,nextReport]=await Promise.all([fetchProducts(session.token),fetchSales(session.token,salesFilters),fetchDashboard(session.token),refreshReport()]);setProducts(nextProducts);setSales(nextSales);setDashboardSummary(nextDashboard);setReportSummary(nextReport);return created};
  const loadSaleDetail=async id=>fetchSale(session.token,id);
  const openSaleForEdit=async id=>{const detail=await fetchSale(session.token,id);setEditingSale(detail);openPage("scanSales");return detail};
  const openSettlement=async sale=>{setSettlementSale(sale);setSettlementError("");setSettlementLoading(true);openPage("saleSettlement");try{setSettlementSale(await fetchSale(session.token,sale.databaseId))}catch(error){setSettlementError(error.message)}finally{setSettlementLoading(false)}};
  const openDelivery=async saleOrId=>{const id=typeof saleOrId==="object"?saleOrId.databaseId:saleOrId;setDeliverySale(typeof saleOrId==="object"?saleOrId:null);setDeliveryError("");setDeliveryLoading(true);openPage("deliveryNote");try{setDeliverySale(await fetchSale(session.token,id))}catch(error){setDeliveryError(error.message)}finally{setDeliveryLoading(false)}};
  const loadPickingDetail=async id=>fetchPickingSale(session.token,id);
  const openPickingNote=async saleOrId=>{const id=typeof saleOrId==="object"?saleOrId.databaseId:saleOrId;setDeliverySale(typeof saleOrId==="object"?saleOrId:null);setDeliveryError("");setDeliveryLoading(true);openPage("pickingNote");try{setDeliverySale(await fetchPickingSale(session.token,id))}catch(error){setDeliveryError(error.message)}finally{setDeliveryLoading(false)}};
  const addSalePayment=async payment=>{if(!settlementSale?.databaseId)return;await createSalePaymentRequest(session.token,settlementSale.databaseId,payment);const [detail,nextSales]=await Promise.all([fetchSale(session.token,settlementSale.databaseId),fetchSales(session.token,salesFilters)]);setSettlementSale(detail);setSales(nextSales);return detail};
  const changeSale=async(id,sale)=>{await updateSaleRequest(session.token,id,sale);const [nextProducts,nextSales,nextDashboard,nextReport,detail]=await Promise.all([fetchProducts(session.token),fetchSales(session.token,salesFilters),fetchDashboard(session.token),refreshReport(),fetchSale(session.token,id)]);setProducts(nextProducts);setSales(nextSales);setDashboardSummary(nextDashboard);setReportSummary(nextReport);setEditingSale(detail);return detail};
  const changeSaleStatus=async(id,changes)=>{await updateSaleStatusRequest(session.token,id,changes);setSales(current=>current.map(sale=>sale.databaseId===id?{...sale,...changes}:sale));if(typeof changes.stockDeducted==="boolean"){try{const [nextProducts,nextDashboard,nextReport]=await Promise.all([fetchProducts(session.token),fetchDashboard(session.token),refreshReport()]);setProducts(nextProducts);setDashboardSummary(nextDashboard);setReportSummary(nextReport)}catch(error){handleError(error)}}};
  const createInvoice=async(id,data)=>{const created=await createInvoiceRequest(session.token,id,data);const [nextSales,nextInvoices]=await Promise.all([fetchSales(session.token,salesFilters),fetchInvoices(session.token)]);setSales(nextSales);setInvoices(nextInvoices);return created};
  const loadInvoiceDetail=async id=>fetchInvoice(session.token,id);
  const loadInvoiceSales=async(filters=defaultSalesFilters())=>fetchSales(session.token,filters);
  const stornoInvoice=async(id,reason)=>{const created=await stornoInvoiceRequest(session.token,id,reason);setInvoices(await fetchInvoices(session.token));return created};
  const correctInvoice=async(id,data)=>{const created=await correctInvoiceRequest(session.token,id,data);setInvoices(await fetchInvoices(session.token));return created};
  const openInvoicePdf=async(id,download=false)=>{const printWindow=!download?window.open("","_blank"):null;try{const blob=await fetchInvoicePdf(session.token,id),url=URL.createObjectURL(blob);if(download){const link=document.createElement("a");link.href=url;link.download=`invoice-${id}.pdf`;document.body.appendChild(link);link.click();link.remove()}else if(printWindow){printWindow.location.href=url}else window.open(url,"_blank");setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(error){printWindow?.close();setDataError(error.message)}};
  const addUser=async(user)=>{const created=await createUserRequest(session.token,user);setUsers(current=>[...current,created])};
  const changeUser=async(id,changes)=>{const updated=await updateUserRequest(session.token,id,changes);setUsers(current=>current.map(user=>user.id===updated.id?updated:user))};
  const saveSystemSettings=async values=>{const updated=await updateSettingsRequest(session.token,values);setSystemSettings(updated);return updated};
  if(!session?.user)return <Login onLogin={login}/>;
  const contentByTarget={
    dashboard:<Dashboard products={products} customers={customers} sales={sales} summary={dashboardSummary} setPage={openPage} lowStockThreshold={systemSettings.lowStockThreshold}/>,
    products:<Products products={products} categories={categoryRecords} onCreate={addProduct} onUpdate={changeProduct} onUploadImage={uploadProductImage} onDeleteImage={removeProductImage} onLoad={loadProducts} onLoadDetail={loadProductDetail} loading={dataLoading} error={dataError} canCreate={["admin","purchasing","warehouse"].includes(session.user.role)} canEdit={["admin","purchasing","warehouse"].includes(session.user.role)} canUpload={["admin","purchasing","warehouse","sales"].includes(session.user.role)} lowStockThreshold={systemSettings.lowStockThreshold}/>,
    categories:<CategoriesPage categories={categoryRecords} onCreate={addCategory} onUpdate={changeCategory} onUploadImage={uploadCategoryImage} onDeleteImage={removeCategoryImage} canManage={["admin","purchasing","warehouse"].includes(session.user.role)} loading={dataLoading} error={dataError}/>,
    purchases:<Purchases purchases={purchases} products={products} onCreate={addPurchase} onRefresh={refreshPurchases} loading={dataLoading} error={dataError} defaultWarehouse={systemSettings.defaultWarehouse} canCreate={["admin","purchasing","warehouse"].includes(session.user.role)}/>,
    inventory:<Products products={products} onCreate={addProduct} onUpdate={changeProduct} onLoad={loadProducts} onLoadDetail={loadProductDetail} loading={dataLoading} error={dataError} lowStockThreshold={systemSettings.lowStockThreshold} inventoryOnly canCreate={["admin","purchasing","warehouse"].includes(session.user.role)} canEdit={false}/>,
    customers:<Customers customers={customers} onCreate={addCustomer} onUpdate={changeCustomer} onLoad={loadCustomers} loading={dataLoading} error={dataError} canCreate={["admin","sales"].includes(session.user.role)}/>,
    sales:<Sales sales={sales} filters={salesFilters} onRefresh={refreshSales} onLoadDetail={loadSaleDetail} onEdit={sale=>openSaleForEdit(sale.databaseId)} onToggleStatus={changeSaleStatus} onOpenSettlement={openSettlement} onOpenDelivery={openDelivery} loading={dataLoading} error={dataError} canEdit={["admin","sales"].includes(session.user.role)} canUpdateStatus={["admin","sales"].includes(session.user.role)} canSettle={["admin","sales","finance"].includes(session.user.role)}/>,pos:<POS products={products} customers={customers} sale={editingSale} onSaveSale={addSale} onUpdateSale={changeSale} onCloseEdit={()=>setEditingSale(null)} onOpenDelivery={openDelivery} defaultCurrency={systemSettings.defaultCurrency}/>,
    invoiceList:<InvoiceManagementList invoices={invoices} onRefresh={refreshInvoices} onOpenPdf={openInvoicePdf} onLoadSale={loadSaleDetail} onLoadInvoice={loadInvoiceDetail} onCreate={createInvoice} onStorno={stornoInvoice} onCorrect={correctInvoice} settings={systemSettings} loading={dataLoading} error={dataError} canManage={["admin","finance"].includes(session.user.role)}/>,
    issueInvoice:<InvoiceIssuePage sales={sales} invoices={invoices} onLoadSales={loadInvoiceSales} onLoadSale={loadSaleDetail} onCreate={createInvoice} onRefreshInvoices={refreshInvoices} onOpenPdf={openInvoicePdf} settings={systemSettings} loading={dataLoading} error={dataError}/>,
    pickingLists:<PickingLists sales={pickingSales} filters={pickingFilters} onRefresh={refreshPickingSales} onLoadDetail={loadPickingDetail} onPrint={openPickingNote} loading={dataLoading} error={dataError}/>,
    saleSettlement:<SettlementPage sale={settlementSale} loading={settlementLoading} error={settlementError} onSubmit={addSalePayment} onCancel={()=>{setSettlementSale(null);setSettlementError("");openPage("sales")}}/>,
    deliveryNote:<DeliveryNote sale={deliverySale} loading={deliveryLoading} error={deliveryError} settings={systemSettings} onBack={()=>{setDeliverySale(null);setDeliveryError("");openPage("sales")}}/>,
    pickingNote:<DeliveryNote sale={deliverySale} loading={deliveryLoading} error={deliveryError} settings={systemSettings} hideFinancial onBack={()=>{setDeliverySale(null);setDeliveryError("");openPage("pickingLists")}}/>,
    collectorSales:<CollectorSales products={products} onSaveSale={addSale} onImported={openSaleForEdit} defaultCurrency={systemSettings.defaultCurrency}/>,
    reports:<Reports products={products} summary={reportSummary}/>,
    users:<UserManagementPage currentUser={session.user} users={users} onCreateUser={addUser} onUpdateUser={changeUser} loading={dataLoading} error={dataError}/>,
    settings:<SettingsPage currentUser={session.user} settings={systemSettings} onSaveSettings={saveSystemSettings} onOpenEmployees={()=>openPage("users")}/>
  };
  return <div className="app-shell"><Sidebar page={page} setPage={openPage} open={menuOpen} setOpen={setMenuOpen} role={session.user.role} settings={systemSettings}/>{menuOpen&&<button className="sidebar-scrim" aria-label="关闭菜单" onClick={()=>setMenuOpen(false)}/>}<main className="main-shell"><Header page={page} tabs={openTabs} onSelectTab={setPage} onCloseTab={closePage} user={session.user.username} onLogout={logout} toggleMenu={()=>setMenuOpen(v=>!v)}/><div className="tab-pages">{openTabs.map(tab=><section key={tab} className="tab-page" hidden={page!==tab} aria-hidden={page!==tab}>{contentByTarget[pageTargets[tab]||tab]}</section>)}</div></main></div>;
}
